42	  const writableScopes = [SettingScope.Workspace, SettingScope.User];
43	  const foundInDisabledScopes: ModifiedScope[] = [];
44	  const alreadyEnabledScopes: ModifiedScope[] = [];
45	
46	  for (const scope of writableScopes) {
