94	  settings: LoadedSettings,
95	  skillName: string,
96	  scope: SettingScope,
97	): SkillActionResult {
98	  if (!isLoadableSettingScope(scope)) {
99	    return {
100	      status: 'error',
101	      skillName,
102	      action: 'disable',
103	      modifiedScopes: [],
104	      alreadyInStateScopes: [],
105	      error: `Invalid settings scope: ${scope}`,
106	    };
107	  }
108	
109	  const scopePath = settings.forScope(scope).path;
110	  const currentScopeDisabled =
111	    settings.forScope(scope).settings.skills?.disabled ?? [];
112	
113	  if (currentScopeDisabled.includes(skillName)) {
114	    return {
115	      status: 'no-op',
116	      skillName,
117	      action: 'disable',
118	      modifiedScopes: [],
119	      alreadyInStateScopes: [{ scope, path: scopePath }],
120	    };
121	  }
122	
123	  // Check if it's already disabled in the other writable scope
124	  const otherScope =
125	    scope === SettingScope.Workspace
126	      ? SettingScope.User
127	      : SettingScope.Workspace;
128	  const alreadyDisabledInOther: ModifiedScope[] = [];
129	
130	  if (isLoadableSettingScope(otherScope)) {
131	    const otherScopeDisabled =
132	      settings.forScope(otherScope).settings.skills?.disabled;
133	    if (otherScopeDisabled?.includes(skillName)) {
134	      alreadyDisabledInOther.push({
135	        scope: otherScope,
136	        path: settings.forScope(otherScope).path,
137	      });
138	    }
139	  }
140	
141	  const newDisabled = [...currentScopeDisabled, skillName];
142	  settings.setValue(scope, 'skills.disabled', newDisabled);
143	
144	  return {
145	    status: 'success',
146	    skillName,
147	    action: 'disable',
148	    modifiedScopes: [{ scope, path: scopePath }],
149	    alreadyInStateScopes: alreadyDisabledInOther,
150	  };
151	}
